// Domain: image generation — provider registry behind one gateway seam.
// Runners and agents never see API keys: they write descriptions, the backend
// generates images through these adapters. Adding a provider means appending
// one descriptor below (plus its key in the key store) — no other code changes.
import { redactSecretsText } from "../../shared/redactSecrets.js";

/***
 * MARK: MUSE_IMAGE_MODEL
 * @description Model id for Meta's Muse Image on the Meta Model API.
 * @example MUSE_IMAGE_MODEL => 'muse-image-1.0'
 ***/
export const MUSE_IMAGE_MODEL = "muse-image-1.0";

/***
 * MARK: MUSE_IMAGE_API_BASE_URL
 * @description Default Meta Model API base URL (OpenAI-compatible
 *   `/images/generations` endpoint). Overridable per deploy via
 *   `KAINBAIN_IMAGE_GEN_MUSE_BASE_URL` (else `META_MODEL_API_BASE_URL`).
 * @example MUSE_IMAGE_API_BASE_URL => 'https://api.meta.ai/v1'
 ***/
export const MUSE_IMAGE_API_BASE_URL = "https://api.meta.ai/v1";

/***
 * MARK: IMAGE_GEN_DEFAULT_SIZE
 * @description The single fixed image size for v1 (one size for every image
 *   question — no per-question size field yet).
 * @example IMAGE_GEN_DEFAULT_SIZE => '1024x1024'
 ***/
export const IMAGE_GEN_DEFAULT_SIZE = "1024x1024";

/***
 * MARK: IMAGE_GEN_TIMEOUT_MS
 * @description Per-request timeout for provider calls. Muse Image is agentic
 *   (it plans and revises before returning), so this is generous — generation
 *   always runs in the background, never on a request path.
 * @example IMAGE_GEN_TIMEOUT_MS => 120000
 ***/
export const IMAGE_GEN_TIMEOUT_MS = 120000;

/***
 * MARK: MOCK_IMAGE_PNG_BASE64
 * @description Deterministic 1x1 PNG returned by the mock provider (offline
 *   tests, UI states, and plumbing checks — no network, no key, no cost).
 * @example Buffer.from(MOCK_IMAGE_PNG_BASE64, 'base64').length > 0 => true
 ***/
export const MOCK_IMAGE_PNG_BASE64 =
	"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";

/***
 * MARK: IMAGE_GEN_PROMPT_MAX_LENGTH
 * @description Longest prompt sent to a provider (over-long agent descriptions
 *   fail that image with a fallback instead of hitting provider limits).
 * @example IMAGE_GEN_PROMPT_MAX_LENGTH => 4000
 ***/
export const IMAGE_GEN_PROMPT_MAX_LENGTH = 4000;

/***
 * MARK: resolveMuseApiBaseUrl
 * @description Effective Muse API base: explicit deploy override first, then
 *   the ecosystem `META_MODEL_API_BASE_URL`, then the Meta default.
 * @example resolveMuseApiBaseUrl() => 'https://api.meta.ai/v1'
 ***/
export const resolveMuseApiBaseUrl = () => {
	const override = [process.env.KAINBAIN_IMAGE_GEN_MUSE_BASE_URL, process.env.META_MODEL_API_BASE_URL]
		.map((v) => (typeof v === "string" ? v.trim().replace(/\/+$/, "") : ""))
		.find((v) => v && /^https?:\/\//i.test(v));
	return override || MUSE_IMAGE_API_BASE_URL;
};

const assertValidPrompt = (prompt) => {
	if (typeof prompt !== "string" || !prompt.trim()) {
		const err = new Error("Image prompt must be a non-empty string");
		err.statusCode = 400;
		err.code = "INVALID_IMAGE_GEN_PROMPT";
		throw err;
	}
	if (prompt.length > IMAGE_GEN_PROMPT_MAX_LENGTH) {
		const err = new Error(
			`Image prompt exceeds ${IMAGE_GEN_PROMPT_MAX_LENGTH} chars`,
		);
		err.statusCode = 400;
		err.code = "INVALID_IMAGE_GEN_PROMPT";
		throw err;
	}
	return prompt;
};

// Strictly decodes an inline base64 payload: `Buffer.from(x, "base64")`
// silently skips invalid characters (never throws), so without this check a
// corrupt provider response would be written to disk as garbage bytes
// instead of failing the image with a descriptions fallback.
const decodeBase64Image = (b64) => {
	const compact = String(b64).replace(/\s+/g, "");
	if (compact.length === 0 || compact.length % 4 !== 0) return null;
	if (!/^[A-Za-z0-9+/]*={0,2}$/.test(compact)) return null;
	const bytes = Buffer.from(compact, "base64");
	return bytes.length > 0 ? bytes : null;
};

// Picks the first usable image payload out of an OpenAI-compatible response:
// inline base64 first (no second request), then a fetchable https URL. The
// `images[]` spellings cover Meta's documented `image_url` variant.
const extractImageRef = (payload) => {
	const lists = [];
	if (Array.isArray(payload?.data)) lists.push(payload.data);
	if (Array.isArray(payload?.images)) lists.push(payload.images);
	const items = lists.flat().filter((item) => item && typeof item === "object");
	for (const item of items) {
		const b64 = item.b64_json ?? item.b64 ?? item.image_base64 ?? item.base64;
		if (typeof b64 === "string" && b64.trim()) return { b64: b64.trim() };
	}
	for (const item of items) {
		const url = item.url ?? item.image_url;
		if (typeof url === "string" && /^https:\/\//i.test(url.trim())) {
			return { url: url.trim() };
		}
	}
	return null;
};

const fetchWithTimeout = async (fetchImpl, url, { timeoutMs, ...init }) => {
	const impl = fetchImpl || globalThis.fetch;
	if (typeof impl !== "function") {
		const err = new Error("No fetch implementation available for image generation");
		err.statusCode = 500;
		err.code = "IMAGE_GEN_NO_FETCH";
		throw err;
	}
	// Raced locally (not just signalled): a hung transport that ignores the
	// abort signal must still lose the race so background jobs cannot wedge.
	const controller = new AbortController();
	let timer;
	const timeoutPromise = new Promise((_, reject) => {
		timer = setTimeout(() => {
			controller.abort();
			const timeout = new Error(`Image request timed out after ${timeoutMs}ms`);
			timeout.statusCode = 504;
			timeout.code = "IMAGE_GEN_TIMEOUT";
			reject(timeout);
		}, timeoutMs);
	});
	try {
		return await Promise.race([
			impl(url, { ...init, signal: controller.signal }),
			timeoutPromise,
		]);
	} finally {
		clearTimeout(timer);
	}
};

/***
 * MARK: generateMockImage
 * @description Deterministic offline generation: validates the prompt and
 *   returns the fixture PNG. No network, no key, no cost.
 * @example (await generateMockImage({ prompt: 'a login screen' })).length > 0 => true
 * @param {Object} [opts]
 * @param {string} [opts.prompt] - Image description.
 * @returns {Promise<Buffer>} PNG bytes.
 ***/
export const generateMockImage = async ({ prompt } = {}) => {
	assertValidPrompt(prompt);
	return Buffer.from(MOCK_IMAGE_PNG_BASE64, "base64");
};

/***
 * MARK: generateMuseImage
 * @description Text-to-image via Muse Image (`muse-image-1.0`) on the Meta
 *   Model API (OpenAI-compatible `POST /images/generations`, API-key auth).
 *   Accepts inline `b64_json` or a follow-up `url` response. The key never
 *   appears in errors; provider error bodies are truncated and redacted.
 * @example (await generateMuseImage({ prompt: 'x', apiKey: 'k', fetchImpl: stub })).length > 0 => true
 * @param {Object} [opts]
 * @param {string} [opts.prompt] - Image description.
 * @param {string} [opts.size] - Requested size (defaults to IMAGE_GEN_DEFAULT_SIZE).
 * @param {string} [opts.apiKey] - Meta Model API key (secret — never logged).
 * @param {Function} [opts.fetchImpl] - Fetch override (tests).
 * @param {number} [opts.timeoutMs] - Per-request timeout (defaults to IMAGE_GEN_TIMEOUT_MS).
 * @returns {Promise<Buffer>} Image bytes.
 ***/
export const generateMuseImage = async ({
	prompt,
	size = IMAGE_GEN_DEFAULT_SIZE,
	apiKey,
	fetchImpl,
	timeoutMs = IMAGE_GEN_TIMEOUT_MS,
} = {}) => {
	assertValidPrompt(prompt);
	if (typeof apiKey !== "string" || !apiKey.trim()) {
		const err = new Error("Muse image provider has no API key saved");
		err.statusCode = 400;
		err.code = "IMAGE_GEN_NO_KEY";
		throw err;
	}
	const base = resolveMuseApiBaseUrl();
	let response;
	try {
		response = await fetchWithTimeout(fetchImpl, `${base}/images/generations`, {
			timeoutMs,
			method: "POST",
			headers: {
				"content-type": "application/json",
				authorization: `Bearer ${apiKey}`,
			},
			body: JSON.stringify({
				model: MUSE_IMAGE_MODEL,
				prompt,
				size: size || IMAGE_GEN_DEFAULT_SIZE,
				n: 1,
				response_format: "b64_json",
			}),
		});
	} catch (err) {
		if (err?.code === "IMAGE_GEN_TIMEOUT") throw err;
		const wrapped = new Error(`Muse image request failed: ${err?.message || "network error"}`);
		wrapped.statusCode = 502;
		wrapped.code = "IMAGE_GEN_PROVIDER_ERROR";
		throw wrapped;
	}
	if (!response || response.ok !== true) {
		const status = response?.status || "unknown";
		let snippet = "";
		try {
			snippet = String(await response?.text?.()).slice(0, 200);
		} catch {
			snippet = "";
		}
		const err = new Error(
			`Muse image request failed (HTTP ${status})${snippet ? `: ${redactSecretsText(snippet)}` : ""}`,
		);
		err.statusCode = 502;
		err.code = "IMAGE_GEN_PROVIDER_ERROR";
		throw err;
	}
	let payload = null;
	try {
		payload = await response.json();
	} catch {
		payload = null;
	}

	}
	const ref = extractImageRef(payload);
	if (!ref) {
		const err = new Error("Muse image response carried no usable image");
		err.statusCode = 502;
		err.code = "IMAGE_GEN_PROVIDER_ERROR";
		throw err;
	}
	if (ref.b64) {
		const bytes = decodeBase64Image(ref.b64);
		if (!bytes) {
			const err = new Error("Muse image response carried invalid base64");
			err.statusCode = 502;
			err.code = "IMAGE_GEN_PROVIDER_ERROR";
			throw err;
		}
		return bytes;
	}
	const fileResponse = await fetchWithTimeout(fetchImpl, ref.url, { timeoutMs });
	if (!fileResponse || fileResponse.ok !== true) {
		const err = new Error(
			`Muse image download failed (HTTP ${fileResponse?.status || "unknown"})`,
		);
		err.statusCode = 502;
		err.code = "IMAGE_GEN_PROVIDER_ERROR";
		throw err;
	}
	const arrayBuffer = await fileResponse.arrayBuffer();
	return Buffer.from(arrayBuffer);
};

const REGISTRY = [
	{
		id: "muse",
		label: "Muse Image (Meta)",
		description: "Meta Muse Image via the Meta Model API (~$0.01/image). Needs an API key.",
		requiresKey: true,
		generate: generateMuseImage,
	},
	{
		id: "mock",
		label: "Mock (offline tests)",
		description: "Deterministic fixture PNG. No network, no key, no cost.",
		requiresKey: false,
		generate: generateMockImage,
	},
];

/***
 * MARK: listImageGenProviders
 * @description Public provider catalogue (id/label only — never keys or the
 *   generate functions themselves). The skill dropdown and the settings tab
 *   both render from this list.
 * @example listImageGenProviders().map((p) => p.id) => ['muse', 'mock']
 ***/
export const listImageGenProviders = () =>
	REGISTRY.map(({ id, label, description, requiresKey }) => ({
		id,
		label,
		description,
		requiresKey,
	}));

/***
 * MARK: getImageGenProvider
 * @description One registered provider adapter by id, or null when unknown.
 * @example getImageGenProvider('muse')?.id => 'muse'
 * @param {string} providerId
 * @returns {Object|null}
 ***/
export const getImageGenProvider = (providerId) =>
	REGISTRY.find((entry) => entry.id === providerId) || null;

/***
 * MARK: isKnownImageGenProvider
 * @description Whether an id names a registered provider.
 * @example isKnownImageGenProvider('muse') => true
 * @param {string} providerId
 * @returns {boolean}
 ***/
export const isKnownImageGenProvider = (providerId) =>
	REGISTRY.some((entry) => entry.id === providerId);

/***
 * MARK: generateImage
 * @description Gateway entry point: generates one image through the named
 *   provider. Unknown providers fail safe with `UNKNOWN_IMAGE_GEN_PROVIDER`
 *   (the survey job turns that into a descriptions fallback, never a crash).
 * @example (await generateImage({ providerId: 'mock', prompt: 'x' })).length > 0 => true
 * @param {Object} [opts]
 * @param {string} [opts.providerId] - Registered provider id.
 * @param {string} [opts.prompt] - Image description.
 * @param {string} [opts.size] - Requested size.
 * @param {string} [opts.apiKey] - Provider API key (secret — never logged).
 * @param {Function} [opts.fetchImpl] - Fetch override (tests).
 * @param {number} [opts.timeoutMs] - Per-request timeout.
 * @returns {Promise<Buffer>} Image bytes.
 ***/
export const generateImage = async ({ providerId, ...rest } = {}) => {
	const provider = getImageGenProvider(providerId);
	if (!provider) {
		const err = new Error(`Unknown image provider: ${String(providerId)}`);
		err.statusCode = 400;
		err.code = "UNKNOWN_IMAGE_GEN_PROVIDER";
		throw err;
	}
	return provider.generate(rest);
};

// Domain: image generation — server-owned API key store for survey image providers.
// Mirrors the prompt-layout atomic-store posture: a 0600 JSON file under the
// server-owned `~/.kainbain/image-gen/` dir (override via KAINBAIN_IMAGE_GEN_DIR),
// tmp-file + rename writes, and missing/corrupt files reading as "no stored
// key". A per-provider env override (KAINBAIN_IMAGE_GEN_<PROVIDER>_API_KEY)
// always wins over the stored file. Keys are never logged and never leave
// this module except to the provider call itself.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/***
 * MARK: IMAGE_GEN_KEYS_FILE_NAME
 * @description File name of the stored key map inside the image-gen dir.
 * @example IMAGE_GEN_KEYS_FILE_NAME => 'image-gen-keys.json'
 ***/
export const IMAGE_GEN_KEYS_FILE_NAME = "image-gen-keys.json";

/***
 * MARK: IMAGE_GEN_KEY_MAX_LENGTH
 * @description Longest accepted API key (over-long input is a misconfiguration,
 *   not a key, and is rejected on write).
 * @example IMAGE_GEN_KEY_MAX_LENGTH => 4096
 ***/
export const IMAGE_GEN_KEY_MAX_LENGTH = 4096;

const PROVIDER_ID_PATTERN = /^[a-z0-9][a-z0-9_-]{0,31}$/;

// Monotonic counter so concurrent writes from this process never share a
// tmp file (the pid alone collides when two PUTs race in one process).
let tmpWriteCounter = 0;

/***
 * MARK: isValidImageGenProviderId
 * @description Strict validator for provider ids carried in routes and the key
 *   file: a lowercase slug that can never traverse (`..`, slashes, and
 *   uppercase are all rejected — ids are matched case-sensitively).
 * @example isValidImageGenProviderId('muse') => true
 * @example isValidImageGenProviderId('../x') => false
 * @param {*} value
 * @returns {boolean}
 ***/
export const isValidImageGenProviderId = (value) => {
	if (typeof value !== "string") return false;
	return PROVIDER_ID_PATTERN.test(value);
};

/***
 * MARK: resolveImageGenDir
 * @description Default on-disk home for the image-gen key file. Explicit
 *   `KAINBAIN_IMAGE_GEN_DIR` wins (tests and isolated deploys); otherwise
 *   `~/.kainbain/image-gen`, mirroring the prompt-layout `~/.kainbain`
 *   convention.
 * @example resolveImageGenDir() => '/home/server/.kainbain/image-gen'
 ***/
export const resolveImageGenDir = () => {
	const override =
		typeof process.env.KAINBAIN_IMAGE_GEN_DIR === "string"
			? process.env.KAINBAIN_IMAGE_GEN_DIR.trim()
			: "";
	if (override) return override;
	return path.join(os.homedir(), ".kainbain", "image-gen");
};

/***
 * MARK: envKeyNameForProvider
 * @description The env override name for one provider's API key
 *   (`KAINBAIN_IMAGE_GEN_<PROVIDER>_API_KEY`), or null for an invalid id.
 * @example envKeyNameForProvider('muse') => 'KAINBAIN_IMAGE_GEN_MUSE_API_KEY'
 * @param {string} providerId
 * @returns {string|null}
 ***/
export const envKeyNameForProvider = (providerId) => {
	if (!isValidImageGenProviderId(providerId)) return null;
	const slug = providerId.toUpperCase().replace(/[^A-Z0-9]+/g, "_");
	return `KAINBAIN_IMAGE_GEN_${slug}_API_KEY`;
};

const keysFilePath = (dir) => path.join(path.resolve(dir), IMAGE_GEN_KEYS_FILE_NAME);

const readStoredKeys = (dir) => {
	/* eslint-disable-next-line security/detect-non-literal-fs-filename -- dir is server-owned image-gen state, not request input */
	const raw = fs.readFileSync(keysFilePath(dir), "utf8");
	const parsed = JSON.parse(raw);
	if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
	const keys = parsed.keys;
	if (!keys || typeof keys !== "object" || Array.isArray(keys)) return {};
	return keys;
};

const storedKeyFor = (dir, providerId) => {
	let keys = {};
	try {
		keys = readStoredKeys(dir);
	} catch {
		return "";
	}
	const entry = keys[providerId];
	/* eslint-disable-next-line security/detect-object-injection -- providerId is validated before every call */
	const raw = typeof entry === "string" ? entry : entry?.key;
	return typeof raw === "string" ? raw.trim() : "";
};

/***
 * MARK: getImageGenKey
 * @description The effective API key for one provider: the env override when
 *   set, else the stored file key, else "". Callers must never log the
 *   result — it is secret material for the provider call only.
 * @example getImageGenKey({ providerId: 'muse', dir: '/tmp/kb-x' }) => ''
 * @param {Object} [opts]
 * @param {string} [opts.providerId] - Registered provider id.
 * @param {string} [opts.dir] - Key store dir (defaults to resolveImageGenDir()).
 * @returns {string}
 ***/
export const getImageGenKey = ({ providerId, dir } = {}) => {
	if (!isValidImageGenProviderId(providerId)) return "";
	const envName = envKeyNameForProvider(providerId);
	const fromEnv =
		envName && typeof process.env[envName] === "string"
			? process.env[envName].trim()
			: "";
	if (fromEnv) return fromEnv;
	const home = dir || resolveImageGenDir();
	if (!home || typeof home !== "string") return "";
	return storedKeyFor(home, providerId);
};

/***
 * MARK: describeImageGenKey
 * @description Key presence for one provider without exposing the key: where
 *   the effective key comes from (`env` wins over `stored`), or unconfigured.
 *   This is the only shape routes and the UI ever see.
 * @example describeImageGenKey({ providerId: 'muse', dir: '/tmp/kb-x' }) => ({ configured: false, source: null })
 * @param {Object} [opts]
 * @param {string} [opts.providerId] - Registered provider id.
 * @param {string} [opts.dir] - Key store dir (defaults to resolveImageGenDir()).
 * @returns {{ configured: boolean, source: 'env'|'stored'|null }}
 ***/
export const describeImageGenKey = ({ providerId, dir } = {}) => {
	if (!isValidImageGenProviderId(providerId)) {
		return { configured: false, source: null };
	}
	const envName = envKeyNameForProvider(providerId);
	const fromEnv =
		envName && typeof process.env[envName] === "string"
			? process.env[envName].trim()
			: "";
	if (fromEnv) return { configured: true, source: "env" };
	const home = dir || resolveImageGenDir();
	if (!home || typeof home !== "string") return { configured: false, source: null };
	return storedKeyFor(home, providerId)
		? { configured: true, source: "stored" }
		: { configured: false, source: null };
};

/***
 * MARK: assertValidImageGenKeyForWrite
 * @description Strict write-path validation for an API key: a trimmed
 *   1–4096 char single-line string. Anything else throws a 400
 *   `INVALID_IMAGE_GEN_KEY` without touching the store.
 * @example assertValidImageGenKeyForWrite('sk-abc') => 'sk-abc'
 * @param {*} value
 * @returns {string} The trimmed key.
 ***/
export const assertValidImageGenKeyForWrite = (value) => {
	const fail = () => {
		const err = new Error(
			"Image provider key must be a non-empty single-line string (max 4096 chars)",
		);
		err.statusCode = 400;
		err.code = "INVALID_IMAGE_GEN_KEY";
		throw err;
	};
	if (typeof value !== "string") fail();
	const trimmed = value.trim();
	if (!trimmed || trimmed.length > IMAGE_GEN_KEY_MAX_LENGTH) fail();
	if (/[\r\n\0]/.test(trimmed)) fail();
	return trimmed;
};

const writeKeysFile = (dir, keys) => {
	const resolvedDir = path.resolve(dir);
	/* eslint-disable-next-line security/detect-non-literal-fs-filename -- dir is server-owned image-gen state, not request input */
	fs.mkdirSync(resolvedDir, { recursive: true, mode: 0o700 });
	tmpWriteCounter += 1;
	const tmp = path.join(
		resolvedDir,
		`.${IMAGE_GEN_KEYS_FILE_NAME}.tmp-${process.pid}-${tmpWriteCounter}`,
	);
	/* eslint-disable-next-line security/detect-non-literal-fs-filename -- dir is server-owned image-gen state, not request input */
	fs.writeFileSync(tmp, JSON.stringify(keys, null, 2), { mode: 0o600 });
	try {
		/* eslint-disable-next-line security/detect-non-literal-fs-filename -- dir is server-owned image-gen state, not request input */
		fs.chmodSync(tmp, 0o600);
	} catch {
		// Best-effort: the write mode already requested 0600.
	}
	/* eslint-disable-next-line security/detect-non-literal-fs-filename -- dir is server-owned image-gen state, not request input */
	fs.renameSync(tmp, path.join(resolvedDir, IMAGE_GEN_KEYS_FILE_NAME));
};

/***
 * MARK: setImageGenKey
 * @description Stores one provider's API key (0600, crash-safe tmp + rename).
 *   Unknown provider ids throw a 400 `UNKNOWN_IMAGE_GEN_PROVIDER`; invalid
 *   keys throw `INVALID_IMAGE_GEN_KEY`. Never returns or logs the key.
 * @example setImageGenKey({ providerId: 'muse', key: 'sk-abc', dir }) => ({ providerId: 'muse', configured: true })
 * @param {Object} [opts]
 * @param {string} [opts.providerId] - Registered provider id.
 * @param {string} [opts.key] - Raw API key.
 * @param {string} [opts.dir] - Key store dir (defaults to resolveImageGenDir()).
 * @returns {{ providerId: string, configured: boolean }}
 ***/
export const setImageGenKey = ({ providerId, key, dir } = {}) => {
	if (!isValidImageGenProviderId(providerId)) {
		const err = new Error(`Unknown image provider: ${String(providerId)}`);
		err.statusCode = 400;
		err.code = "UNKNOWN_IMAGE_GEN_PROVIDER";
		throw err;
	}
	const trimmed = assertValidImageGenKeyForWrite(key);
	const home = dir || resolveImageGenDir();
	if (!home || typeof home !== "string") {
		throw new Error("setImageGenKey requires a dir");
	}
	let keys = {};
	try {
		keys = readStoredKeys(home);
	} catch {
		keys = {};
	}
	/* eslint-disable-next-line security/detect-object-injection -- providerId is validated above */
	keys[providerId] = { key: trimmed, updatedAt: new Date().toISOString() };
	writeKeysFile(home, { keys });
	return { providerId, configured: true };
};

/***
 * MARK: clearImageGenKey
 * @description Removes one provider's stored key (the env override, when set,
 *   keeps the provider configured — reported honestly in the result).
 * @example clearImageGenKey({ providerId: 'muse', dir }) => ({ providerId: 'muse', configured: false })
 * @param {Object} [opts]
 * @param {string} [opts.providerId] - Registered provider id.
 * @param {string} [opts.dir] - Key store dir (defaults to resolveImageGenDir()).
 * @returns {{ providerId: string, configured: boolean }}
 ***/
export const clearImageGenKey = ({ providerId, dir } = {}) => {
	if (!isValidImageGenProviderId(providerId)) {
		const err = new Error(`Unknown image provider: ${String(providerId)}`);
		err.statusCode = 400;
		err.code = "UNKNOWN_IMAGE_GEN_PROVIDER";
		throw err;
	}
	const home = dir || resolveImageGenDir();
	if (!home || typeof home !== "string") {
		throw new Error("clearImageGenKey requires a dir");
	}
	let keys = {};
	try {
		keys = readStoredKeys(home);
	} catch {
		keys = {};
	}
	/* eslint-disable-next-line security/detect-object-injection -- providerId is validated above */
	delete keys[providerId];
	writeKeysFile(home, { keys });
	const { configured } = describeImageGenKey({ providerId, dir: home });
	return { providerId, configured };
};

// Domain: image generation — background survey-image job (backend gateway).
// The runner/agent only writes description options; this job turns them into
// pictures at park time (fire-and-forget, so the park itself never waits on
// provider latency) and on survey reads (crash recovery). Images land in the
// task folder's assets/ via the taskAssets helpers; per-image status is
// spliced into the round JSON via updateSurveyImages. Descriptions are the
// durable contract — images are derived artifacts, and any failure degrades
// to the descriptions fallback instead of blocking the survey.
import fs from "node:fs";
import { _atomicWriteFileSync } from "../house/index.js";
import { _appendProcessLog } from "../watch/index.js";
import {
	readSurvey,
	resolveSurveyPath,
	updateSurveyImages,
	withSurveyFileWriteLock,
} from "../work/taskSurvey.js";
import {
	resolveTaskAssetFile,
	sanitizeImageName,
	taskAssetRelPath,
	writeTaskImage,
} from "../work/taskAssets.js";
import { getImageGenKey } from "./keyStore.js";
import {
	IMAGE_GEN_DEFAULT_SIZE,
	generateImage,
	getImageGenProvider,
} from "./providers.js";

/***
 * MARK: SURVEY_IMAGE_CAP
 * @description Most generated images one survey file may hold (cost guard:
 *   3 full image questions at ~$0.01/image). Options beyond the cap get a
 *   terminal `cap` failure entry and render descriptions-only.
 * @example SURVEY_IMAGE_CAP => 12
 ***/
export const SURVEY_IMAGE_CAP = 12;

/***
 * MARK: IMAGE_GEN_DISABLED
 * @description The question-me `imageGen` value meaning "no image questions"
 *   (the default — the job no-ops and the prompt section is removed).
 * @example IMAGE_GEN_DISABLED => 'none'
 ***/
export const IMAGE_GEN_DISABLED = "none";

const shortError = (message) =>
	String(message || "unknown error").replace(/\s+/g, " ").trim().slice(0, 160);

/***
 * MARK: imageGenRequestedBy
 * @description Raw `imageGen` value from a stage's question-me attachment
 *   config (null when the stage carries no usable override). Uses the same
 *   tolerant scalar coercion as skill keyword resolution (skillInjection):
 *   strings pass through, finite numbers/booleans stringify, and objects or
 *   arrays (e.g. a wrapped `{ value: 'muse' }`) are ignored — so a malformed
 *   override fails safe to the default instead of stringifying to
 *   "[object Object]", keeping the prompt and the generation job in agreement.
 * @example imageGenRequestedBy({ skills: [{ name: 'question-me', config: { imageGen: 'muse' } }] }) => 'muse'
 * @example imageGenRequestedBy({ skills: [{ name: 'question-me', config: { imageGen: { value: 'muse' } } }] }) => null
 * @param {Object} [stage] - Stage (or attachment) carrying question-me config.
 * @returns {string|null}
 ***/
export const imageGenRequestedBy = (stage) => {
	const entries = Array.isArray(stage?.skills) ? stage.skills : [];
	const found = entries.find((entry) => {
		const name = typeof entry === "string" ? entry : entry?.name;
		return typeof name === "string" && name.trim().toLowerCase() === "question-me";
	});
	if (!found || typeof found !== "object") return null;
	const config = found.config && typeof found.config === "object" && !Array.isArray(found.config)
		? found.config
		: {};
	const raw = config.imageGen;
	if (raw === undefined || raw === null) return null;
	if (typeof raw === "string") return raw;
	if ((typeof raw === "number" && Number.isFinite(raw)) || typeof raw === "boolean") {
		return String(raw);
	}
	return null;
};

/***
 * MARK: resolveImageGenProvider
 * @description Effective image provider for a stage (or raw value): a
 *   registered provider id, else `none`. Unknown values fail safe to `none`
 *   (the job logs a warning; the survey falls back to descriptions).
 * @example resolveImageGenProvider('muse') => 'muse'
 * @example resolveImageGenProvider('nope') => 'none'
 * @param {Object|string} [stageOrValue]
 * @returns {string}
 ***/
export const resolveImageGenProvider = (stageOrValue) => {
	const raw =
		typeof stageOrValue === "string" ? stageOrValue : imageGenRequestedBy(stageOrValue);
	const id = String(raw || "").trim().toLowerCase();
	if (!id || id === IMAGE_GEN_DISABLED) return IMAGE_GEN_DISABLED;
	return getImageGenProvider(id) ? id : IMAGE_GEN_DISABLED;
};

/***
 * MARK: surveyImageFileName
 * @description Deterministic asset name for one generated survey image
 *   (`survey-r<round>-<qid>-<i>.png`, sanitized — agent-authored question ids
 *   can carry unsafe characters).
 * @example surveyImageFileName(1, 'q1', 0) => 'survey-r1-q1-0.png'
 * @param {number} round - Round number.
 * @param {string} questionId - Question id.
 * @param {number} index - Option index.
 * @returns {string}
 ***/
export const surveyImageFileName = (round, questionId, index) => {
	const safe = sanitizeImageName(`survey-r${round}-${safeQuestionStem(questionId)}-${index}.png`);
	return safe || `survey-r${round}-image-${index}.png`;
};

// The stem is sanitized BEFORE composing: sanitizing the composed name
// would let a hostile question id (`../../x`) eat the round prefix.
const safeQuestionStem = (questionId) =>
	sanitizeImageName(String(questionId || "").trim() || "question").replace(/\.[^.]*$/, "") ||
	"question";

const sameEntries = (a, b) => {
	if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
	return a.every((entry, i) => JSON.stringify(entry) === JSON.stringify(b[i]));
};

const byOptionIndex = (entries) => {
	const map = new Map();
	for (const entry of Array.isArray(entries) ? entries : []) {
		if (entry && Number.isInteger(entry.option) && !map.has(entry.option)) {
			map.set(entry.option, entry);
		}
	}
	return map;
};

// In-flight jobs by task+file so a park-time kick and concurrent survey reads
// (or a slow provider under polling) share one run instead of stampeding.
const INFLIGHT_JOBS = new Map();

const jobKeyFor = ({ cwd, taskId, surveyFile } = {}) => {
	if (!cwd || !taskId) return null;
	return `${cwd}::${taskId}::${surveyFile || "SURVEY.md"}`;
};

const runSurveyImageJob = async (opts = {}) => {
	const {
		cwd,
		project = null,
		taskId,
		surveyFile = null,
		stage = null,
		rounds: providedRounds,
		imageGenDir,
		fetchImpl,
		retryFailed = false,
	} = opts;
	const summary = {
		providerId: IMAGE_GEN_DISABLED,
		status: "disabled",
		generated: 0,
		failed: 0,
		capped: 0,
		skipped: 0,
		chosenPersisted: 0,
		warnings: [],
		errors: [],
	};
	if (!cwd || !taskId) {
		summary.status = "invalid";
		return summary;
	}
	// Lock key for this survey file (same resolution every writer uses, so a
	// submit splicing answers and this job splicing images[] serialize).
	const lockPath = resolveSurveyPath(cwd, project, taskId, surveyFile || undefined);
	const requested =
		typeof opts.providerId === "string" ? opts.providerId : imageGenRequestedBy(stage);
	const providerId = resolveImageGenProvider(requested);
	summary.providerId = providerId;
	if (
		requested &&
		providerId === IMAGE_GEN_DISABLED &&
		String(requested).trim().toLowerCase() !== IMAGE_GEN_DISABLED
	) {
		summary.warnings.push(
			`Unknown image provider '${requested}' — image generation disabled for this survey.`,
		);
	}
	if (providerId === IMAGE_GEN_DISABLED) {
		summary.status = "disabled";
		return summary;
	}
	const provider = getImageGenProvider(providerId);
	const survey = Array.isArray(providedRounds)
		? { exists: true, rounds: providedRounds }
		: readSurvey(cwd, project, taskId, surveyFile || undefined);
	if (!survey.exists || !Array.isArray(survey.rounds) || survey.rounds.length === 0) {
		summary.status = "no-survey";
		return summary;
	}
	const imageQuestions = [];
	for (const round of survey.rounds) {
		for (const question of round?.questions || []) {
			if (question?.type === "image") imageQuestions.push({ round: round.round, question });
		}
	}
	if (imageQuestions.length === 0) {
		summary.status = "no-image-questions";
		return summary;
	}
	const apiKey = provider.requiresKey ? getImageGenKey({ providerId, dir: imageGenDir }) : "";
	const keyMissing = provider.requiresKey && !apiKey;
	const readyCount = imageQuestions.reduce(
		(n, { question }) =>
			n + (Array.isArray(question.images) ? question.images.filter((e) => e?.status === "ready").length : 0),
		0,
	);
	// Only ready images spend the budget upfront: pending entries are either
	// owned by this run (filled in pass 2) or orphans of a crashed run (they
	// regenerate below and spend one unit each like any other generation).
	let budget = Math.max(0, SURVEY_IMAGE_CAP - readyCount);
	const label = provider.label || providerId;

	// Decides the terminal entry for one option that will NOT be generated
	// this run (unconfigured provider, spent budget, or a failed entry this
	// run must not retry). Returns null when the option needs generation.
	const terminalEntryFor = (optionIndex, existing) => {
		if (keyMissing) {
			return {
				option: optionIndex,
				status: "failed",
				code: "no-key",
				error: `No API key saved for ${label} — add one in System Settings › Images.`,
			};
		}
		if (existing?.status === "failed" && existing?.code === "no-key" && !keyMissing) {
			return null; // Healed: a key exists now, generate below.
		}
		if (existing?.status === "failed" && !retryFailed) return existing;
		if (existing?.status === "ready") return existing;
		// Pending entries regenerate: while a job is in flight the dedupe
		// map owns them, so any pending entry seen here is an orphan of a
		// crashed run (or this run's own pass-1 write, filled in pass 2).
		if (budget <= 0) {
			if (existing?.status === "failed") return existing; // Keep the earlier reason.
			return {
				option: optionIndex,
				status: "failed",
				code: "cap",
				error: `Survey image limit reached (${SURVEY_IMAGE_CAP} per survey) — showing descriptions.`,
			};
		}
		return null;
	};

	// Pass 1: publish pending/terminal entries so the UI can show progress
	// (or an honest fallback) while generation runs.
	const planned = [];
	for (const { round, question } of imageQuestions) {
		const options = Array.isArray(question.options) ? question.options : [];
		const current = Array.isArray(question.images) ? [...question.images] : [];
		const known = byOptionIndex(current);
		const next = [...current];
		const setEntry = (entry) => {
			const at = next.findIndex((e) => e?.option === entry.option);
			if (at >= 0) next[at] = entry;
			else next.push(entry);
		};
		const toGenerate = [];
		for (let i = 0; i < options.length; i += 1) {
			const existing = known.get(i);
			if (existing?.status === "ready") {
				summary.skipped += 1;
				continue;
			}
			const terminal = terminalEntryFor(i, existing);
			if (terminal) {
				const before = next.find((e) => e?.option === i);
				setEntry(terminal);
				if (!before || JSON.stringify(before) !== JSON.stringify(terminal)) {
					if (terminal.status === "failed" && terminal.code === "cap") summary.capped += 1;
					else if (terminal.status === "failed") summary.failed += 1;
				}
				continue;
			}
			budget -= 1;
			const fileName = surveyImageFileName(round, question.id, i);
			setEntry({ option: i, file: `assets/${fileName}`, status: "pending" });
			toGenerate.push({ index: i, prompt: options[i], fileName });
		}
		next.sort((a, b) => (a?.option || 0) - (b?.option || 0));
		if (!sameEntries(current, next)) {
			try {
				await withSurveyFileWriteLock(lockPath, () =>
					updateSurveyImages({
						cwd,
						project,
						taskId,
						...(surveyFile ? { outputFile: surveyFile } : {}),
						round,
						questionId: question.id,
						images: next,
					}),
				);
			} catch (err) {
				summary.errors.push(`r${round}/${question.id}: ${shortError(err?.message)}`);
				// Nothing was published and nothing below will generate for
				// this question, so hand its budget back: later questions
				// must not pay for this write failure with cap entries.
				budget += toGenerate.length;
				continue;
			}
		}
		if (toGenerate.length > 0) planned.push({ round, questionId: question.id, options, entries: next, toGenerate });
	}

	// Pass 2: generate each planned image (one retry unless the failure
	// cannot heal) and splice the outcome per question.
	for (const item of planned) {
		const entries = item.entries.map((e) => ({ ...e }));
		const setEntry = (entry) => {
			const at = entries.findIndex((e) => e?.option === entry.option);
			if (at >= 0) entries[at] = entry;
			else entries.push(entry);
		};
		for (const target of item.toGenerate) {
			let bytes = null;
			let lastError = null;
			for (let attempt = 0; attempt < 2 && !bytes; attempt += 1) {
				try {
					bytes = await generateImage({
						providerId,
						prompt: target.prompt,
						size: IMAGE_GEN_DEFAULT_SIZE,
						apiKey,
						fetchImpl,
					});
				} catch (err) {
					lastError = err;
					if (err?.code === "IMAGE_GEN_NO_KEY" || err?.code === "INVALID_IMAGE_GEN_PROMPT") break;
				}
			}
			if (bytes && bytes.length > 0) {
				try {
					writeTaskImage(cwd, taskId, target.fileName, bytes, project);
					setEntry({ option: target.index, file: `assets/${target.fileName}`, status: "ready" });
					summary.generated += 1;
				} catch (err) {
					setEntry({
						option: target.index,
						status: "failed",
						code: "gen",
						error: shortError(`Could not save the generated image: ${err?.message}`),
					});
					summary.failed += 1;
				}
			} else {
				setEntry({
					option: target.index,
					status: "failed",
					code: "gen",
					error: shortError(`Generation failed: ${lastError?.message || "unknown error"}`),
				});
				summary.failed += 1;
				summary.errors.push(
					`r${item.round}/${item.questionId}#${target.index}: ${shortError(lastError?.message)}`,
				);
			}
		}
		entries.sort((a, b) => (a?.option || 0) - (b?.option || 0));
		try {
			await withSurveyFileWriteLock(lockPath, () =>
				updateSurveyImages({
					cwd,
					project,
					taskId,
					...(surveyFile ? { outputFile: surveyFile } : {}),
					round: item.round,
					questionId: item.questionId,
					images: entries,
				}),
			);
		} catch (err) {
			summary.errors.push(`r${item.round}/${item.questionId}: ${shortError(err?.message)}`);
		}
	}
	// Late chosen-image merge: a submit that landed while pictures were
	// still generating saved answers but no chosen picture (nothing was
	// ready yet). Now that new pictures are ready, retry that merge so the
	// task folder still gains the picked file + survey reference even
	// though the submit already advanced. Reads the file fresh (never the
	// planning read above) and never fails the job.
	if (summary.generated > 0) {
		try {
			const late = await persistChosenSurveyImages({
				cwd,
				project,
				taskId,
				surveyFile,
			});
			summary.chosenPersisted = late.chosen.length;
			for (const errLine of late.errors || []) summary.errors.push(errLine);
		} catch (err) {
			summary.errors.push(shortError(err?.message));
		}
	}
	summary.status = "done";
	return summary;
};

/***
 * MARK: ensureSurveyImages
 * @description Generates the missing images for a survey's image questions
 *   (never throws — every failure lands in the returned summary and as
 *   failed entries with a descriptions fallback). Concurrent calls for the
 *   same task+file share one run. Park sites pass `retryFailed: true` so a
 *   new round also heals earlier failures; survey reads leave it false so a
 *   broken provider cannot be hammered by polling. When new pictures land,
 *   already-submitted answers get their chosen picture persisted, so a
 *   submit that landed mid-generation still leaves a design reference.
 * @example await ensureSurveyImages({ cwd: '/repo', taskId: 't1', stage }) => ({ status: 'done', ... })
 * @param {Object} [opts]
 * @param {string} [opts.cwd] - Project working directory.
 * @param {Object} [opts.project] - Project record (docs-dir aware).
 * @param {string} [opts.taskId] - Task id.
 * @param {string} [opts.surveyFile] - Survey file name (defaults to SURVEY.md).
 * @param {Object} [opts.stage] - Parked stage (resolves the imageGen provider).
 * @param {string} [opts.providerId] - Explicit provider override (tests).
 * @param {Array} [opts.rounds] - Pre-read rounds (skips the file read for planning).
 * @param {string} [opts.imageGenDir] - Key store dir override (tests).
 * @param {Function} [opts.fetchImpl] - Fetch override (tests).
 * @param {boolean} [opts.retryFailed] - Also retry earlier `gen`/`cap` failures.
 * @returns {Promise<Object>} Summary (providerId, status, generated/failed/capped/skipped/chosenPersisted, warnings, errors).
 ***/
export const ensureSurveyImages = (opts = {}) => {
	const key = jobKeyFor(opts);
	if (!key) {
		return Promise.resolve({
			providerId: IMAGE_GEN_DISABLED,
			status: "invalid",
			generated: 0,
			failed: 0,
			capped: 0,
			skipped: 0,
		chosenPersisted: 0,
			warnings: [],
			errors: [],
		});
	}
	const inflight = INFLIGHT_JOBS.get(key);
	if (inflight) return inflight;
	const promise = runSurveyImageJob(opts)
		.catch((err) => ({
			providerId: IMAGE_GEN_DISABLED,
			status: "error",
			generated: 0,
			failed: 0,
			capped: 0,
			skipped: 0,
		chosenPersisted: 0,
			warnings: [],
			errors: [shortError(err?.message)],
		}))
		.finally(() => {
			if (INFLIGHT_JOBS.get(key) === promise) INFLIGHT_JOBS.delete(key);
		});
	INFLIGHT_JOBS.set(key, promise);
	return promise;
};

/***
 * MARK: kickSurveyImageJob
 * @description Fire-and-forget park hook shared by the embedded and
 *   Runner-report finish paths: starts the generation job (which also heals
 *   earlier failures on a new park) and reports its summary to the task log
 *   when it settles. Never throws, never blocks the park.
 * @example kickSurveyImageJob({ store, cwd: '/repo', taskId: 't1', task, stage })
 * @param {Object} [opts]
 * @param {Object} [opts.store] - Task store (for the completion report).
 * @param {string} [opts.cwd] - Project working directory.
 * @param {Object} [opts.project] - Project record (docs-dir aware).
 * @param {string} [opts.taskId] - Task id.
 * @param {Object} [opts.task] - Task entity (receives the report lines).
 * @param {string} [opts.surveyFile] - Survey file name.
 * @param {Object} [opts.stage] - Parked stage (resolves the imageGen provider).
 ***/
export const kickSurveyImageJob = ({ store, cwd, project, taskId, task, surveyFile, stage } = {}) => {
	void ensureSurveyImages({
		cwd,
		project: project || null,
		taskId,
		surveyFile: surveyFile || null,
		stage: stage || null,
		retryFailed: true,
	}).then(
		(summary) => reportSurveyImagesToTask({ store, cwd, task, summary }),
		() => {},
	);
};

/***
 * MARK: reportSurveyImagesToTask
 * @description Appends one job summary to the task's process log (and saves
 *   the task) so the park history shows what image generation did. Silent
 *   (returns null, touches nothing) when the feature is off and there is
 *   nothing to warn about.
 * @example reportSurveyImagesToTask({ store, cwd: '/repo', task, summary }) => ['[INFO] image-gen: ...'] | null
 * @param {Object} [opts]
 * @param {Object} [opts.store] - Task store (for `_saveTaskMarkdown`).
 * @param {string} [opts.cwd] - Project working directory.
 * @param {Object} [opts.task] - Task entity (mutated with log lines).
 * @param {Object} [opts.summary] - `ensureSurveyImages` summary.
 * @returns {string[]|null} Log lines written, or null when silent.
 ***/
export const reportSurveyImagesToTask = ({ store, cwd, task, summary } = {}) => {
	if (!task || !summary) return null;
	const lines = [];
	if (summary.providerId !== IMAGE_GEN_DISABLED) {
		const parts = [];
		if (summary.generated > 0) parts.push(`${summary.generated} generated`);
		if (summary.failed > 0) parts.push(`${summary.failed} failed`);
		if (summary.capped > 0) parts.push(`${summary.capped} over the survey limit`);
		if (summary.skipped > 0) parts.push(`${summary.skipped} already ready`);
		if (summary.chosenPersisted > 0) {
			parts.push(
				`${summary.chosenPersisted} chosen design${summary.chosenPersisted === 1 ? "" : "s"} saved`,
			);
		}
		lines.push(
			`[INFO] image-gen: provider '${summary.providerId}' — ${parts.length > 0 ? parts.join(", ") : "nothing to do"}`,
		);
	}
	for (const warning of summary.warnings || []) lines.push(`[WARN] image-gen: ${warning}`);
	for (const error of (summary.errors || []).slice(0, 3)) lines.push(`[WARN] image-gen: ${error}`);
	if (lines.length === 0) return null;
	for (const line of lines) {
		try {
			_appendProcessLog(task, line);
		} catch {
			// Logging must never break the caller.
		}
	}
	try {
		store?._saveTaskMarkdown?.(cwd, task);
	} catch {
		// Best effort: the summary is also in the returned value.
	}
	return lines;
};

/***
 * MARK: CHOSEN_DESIGNS_HEADING
 * @description Markdown section heading listing the human's picked survey
 *   images (appended to the survey file on submit, updated on re-submit).
 * @example CHOSEN_DESIGNS_HEADING => '## Chosen designs'
 ***/
export const CHOSEN_DESIGNS_HEADING = "## Chosen designs";

/***
 * MARK: chosenSurveyImageFileName
 * @description Stable asset name for a human's picked survey image
 *   (`survey-r<round>-<qid>-chosen.png`, sanitized): re-submits overwrite
 *   the same file, so downstream stages can rely on the path.
 * @example chosenSurveyImageFileName(1, 'q1') => 'survey-r1-q1-chosen.png'
 * @param {number} round - Round number.
 * @param {string} questionId - Question id.
 * @returns {string}
 ***/
export const chosenSurveyImageFileName = (round, questionId) => {
	const safe = sanitizeImageName(`survey-r${round}-${safeQuestionStem(questionId)}-chosen.png`);
	return safe || `survey-r${round}-chosen.png`;
};

// Greedy up to `] ![` so a question id containing `]` still parses (a
// `[^...]` class would stop at the id's own bracket and orphan the entry).
const CHOSEN_ENTRY_PATTERN = /^- \[r(\d+)\/(.+)\] !\[/;

const escapeMarkdownText = (value) =>
	String(value || "").replace(/\s+/g, " ").trim().replace(/[\[\]]/g, "\\$&").slice(0, 200);

/***
 * MARK: upsertChosenDesignsSection
 * @description Returns survey markdown with the `## Chosen designs` reference
 *   section added or merged: each entry is one `- [r<round>/<qid>] ![...](assets/...)`
 *   line keyed by round+question, so re-submits update prior picks in place
 *   instead of duplicating them. Round JSON fences are never touched (pure
 *   markdown surgery around them).
 * @example upsertChosenDesignsSection('# Survey\n', [{ round: 1, questionId: 'qi', text: 'Pick', option: 'dark', file: 'assets/a.png' }]).includes('## Chosen designs') => true
 * @param {string} markdown - Current survey file text.
 * @param {Array<Object>} entries - `{ round, questionId, text, option, file }` picks.
 * @returns {string}
 ***/
export const upsertChosenDesignsSection = (markdown, entries) => {
	const base = typeof markdown === "string" ? markdown : "";
	const picks = (Array.isArray(entries) ? entries : []).filter(
		(e) => e && Number.isFinite(e.round) && e.questionId && e.file,
	);
	if (picks.length === 0) return base;
	const lines = base.split("\n");
	const headerAt = lines.findIndex((line) => line.trim() === CHOSEN_DESIGNS_HEADING);
	const renderEntry = (entry) =>
		`- [r${entry.round}/${entry.questionId}] ![${escapeMarkdownText(`${entry.text || entry.questionId}: ${entry.option || ""}`)}](${entry.file})`;
	// Merge key: entries are keyed r<round>/<qid>; newcomers append, picks
	// for a known key overwrite in place.
	const merged = new Map();
	const intro = [];
	const harvest = (line) => {
		const match = CHOSEN_ENTRY_PATTERN.exec(line.trim());
		if (match) merged.set(`r${match[1]}/${match[2]}`, line.trim());
		else if (line.trim()) intro.push(line);
	};
	let sectionEnd = lines.length;
	if (headerAt >= 0) {
		sectionEnd = lines.length;
		for (let i = headerAt + 1; i < lines.length; i += 1) {
			if (/^##\s+\S/.test(lines[i])) {
				sectionEnd = i;
				break;
			}
		}
		for (let i = headerAt + 1; i < sectionEnd; i += 1) harvest(lines[i]);
	}
	for (const entry of picks) {
		merged.set(`r${entry.round}/${entry.questionId}`, renderEntry(entry));
	}
	const ordered = [...merged.entries()]
		.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
		.map(([, line]) => line);
	// Harvested prose (human annotations) survives updates; fresh sections
	// get the default explainer.
	const introLines = intro.length > 0
		? intro
		: ["Image-question selections, saved automatically when the survey is submitted (re-submitting updates this list)."];
	const section = [CHOSEN_DESIGNS_HEADING, "", ...introLines, "", ...ordered, ""];
	if (headerAt >= 0) {
		const next = [...lines.slice(0, headerAt), ...section, ...lines.slice(sectionEnd)];
		return `${next.join("\n").replace(/\s+$/, "")}\n`;
	}
	return `${base.replace(/\s+$/, "")}\n\n${section.join("\n").replace(/\s+$/, "")}\n`;
};

/***
 * MARK: persistChosenSurveyImages
 * @description Copies every answered image question's picked picture to a
 *   stable `assets/survey-r<round>-<qid>-chosen.png` name and references it
 *   from the survey file's `## Chosen designs` section (markdown only — round
 *   JSON is untouched). Idempotent: re-running with the same answers rewrites
 *   identical bytes. Never throws — persistence failures are reported in the
 *   result so a submit can never fail on them.
 * @example await persistChosenSurveyImages({ cwd: '/repo', taskId: 't1' }) => ({ chosen: [...], sectionWritten: true })
 * @param {Object} [opts]
 * @param {string} [opts.cwd] - Project working directory.
 * @param {Object} [opts.project] - Project record (docs-dir aware).
 * @param {string} [opts.taskId] - Task id.
 * @param {string} [opts.surveyFile] - Survey file name (defaults to SURVEY.md).
 * @param {Array} [opts.rounds] - Pre-read rounds (skips the file read for planning).
 * @returns {Promise<{ chosen: Array, sectionWritten: boolean, errors: Array }>}
 ***/
export const persistChosenSurveyImages = async (opts = {}) => {
	const result = { chosen: [], sectionWritten: false, errors: [] };
	try {
		const { cwd, project = null, taskId, surveyFile = null, rounds: providedRounds } = opts;
		if (!cwd || !taskId) return result;
		const survey = Array.isArray(providedRounds)
			? { exists: true, rounds: providedRounds, markdown: null }
			: readSurvey(cwd, project, taskId, surveyFile || undefined);
		if (!survey.exists || !Array.isArray(survey.rounds)) return result;
		for (const round of survey.rounds) {
			const answers = round?.answers && typeof round.answers === "object" ? round.answers : {};
			for (const question of round?.questions || []) {
				if (question?.type !== "image") continue;
				const selected = answers[question.id]?.selected;
				if (!Array.isArray(selected) || selected.length === 0) continue;
				const optionIndex = (question.options || []).indexOf(selected[0]);
				if (optionIndex < 0) continue;
				const entry = (Array.isArray(question.images) ? question.images : []).find(
					(e) => e?.option === optionIndex && e?.status === "ready",
				);
				if (!entry || typeof entry.file !== "string" || !entry.file) continue;
				const sourceName = entry.file.split("/").pop();
				const sourceFile = resolveTaskAssetFile(cwd, taskId, sourceName, project);
				if (!sourceFile) continue;
				let bytes;
				try {
					/* eslint-disable-next-line security/detect-non-literal-fs-filename -- resolved through the traversal-safe asset helper */
					bytes = fs.readFileSync(sourceFile);
				} catch {
					continue; // Artifact gone (deleted by hand): skip, keep the survey valid.
				}
				const chosenName = chosenSurveyImageFileName(round.round, question.id);
				try {
					writeTaskImage(cwd, taskId, chosenName, bytes, project);
				} catch (err) {
					result.errors.push(`r${round.round}/${question.id}: ${shortError(err?.message)}`);
					continue;
				}
				result.chosen.push({
					round: round.round,
					questionId: question.id,
					text: question.text || "",
					option: selected[0],
					file: taskAssetRelPath(chosenName),
				});
			}
		}
		if (result.chosen.length === 0) return result;
		const filePath = resolveSurveyPath(cwd, project, taskId, surveyFile || undefined);
		if (!filePath) return result;
		// Serialized with the job's splices and answer saves: the fresh read
		// and the section write are one critical section, so a concurrent
		// images[] update can neither be clobbered by, nor clobber, this one.
		// The file is always re-read inside the lock (never the possibly
		// stale planning read above) so the merge sees the latest state.
		await withSurveyFileWriteLock(filePath, () => {
			let before;
			try {
				/* eslint-disable-next-line security/detect-non-literal-fs-filename -- resolved through the survey path helper */
				before = fs.readFileSync(filePath, "utf8");
			} catch {
				return;
			}
			const after = upsertChosenDesignsSection(before, result.chosen);
			if (after !== before) {
				_atomicWriteFileSync(filePath, after);
			}
			result.sectionWritten = true; // ...including idempotent re-submits.
		});
		return result;
	} catch (err) {
		result.errors.push(shortError(err?.message));
		return result;
	}
};

