			taskId: task.id,
			outputFile,
			surveyFile: outputFile,
			status: survey.status,
			advanced: true,
			currentStageId: advanced?.currentStageId || task.currentStageId,
			unknownIds: survey.unknownIds || [],
			rounds: survey.rounds || [],
			errors: survey.errors || [],
