		});
	});

	it("accepts Meta's images[]/image_url spelling via a follow-up download", async () => {
		const imageBytes = Buffer.from("fake-image-bytes");
		const urls = [];
		const fetchImpl = async (url) => {
			urls.push(url);
			if (String(url).endsWith("/images/generations")) {
